"use client";

import dynamic from "next/dynamic";
import { AiToolActivity, type ToolStep } from "./ai-tool-activity";
import type { HistoryMessage } from "@/lib/ai/conversation-history";
import type { FollowUp } from "@/lib/ai/follow-ups";
import Link from "next/link";
import { ChevronRight, ListChecks, LoaderCircle } from "lucide-react";

export const DRAFT_EVENT = "moneo-chat-draft";
/** One-click next steps: prompts fill the composer (the user still sends), links navigate. */
function FollowUps({ items, compact }: { items: FollowUp[]; compact: boolean }) {
  if (!items.length) return null;
  const chip = "rounded-full border border-border px-3 py-1 text-xs text-muted-foreground hover:bg-muted hover:text-foreground";
});

export type ChatItem = Omit<HistoryMessage, "tools"> & { tools?: (string | ToolStep)[]; plan?: string[]; followUps?: FollowUp[] };
export type PendingExchange = { question: string; tools: ToolStep[]; answer?: string; streaming?: boolean; plan?: string[]; steers?: string[] };

/** Message list shared by the AI page and the Ask Moneo panel. */
export function ChatMessages({ messages, pending, compact = false }: { messages: ChatItem[]; pending?: PendingExchange | null; compact?: boolean }) {
  const bubble = `ml-auto w-fit max-w-[85%] whitespace-pre-wrap [overflow-wrap:anywhere] rounded-3xl bg-muted px-4 py-2.5 ${compact ? "text-sm" : "text-[15px]"}`;
  const avatar = <span className={`mt-0.5 flex shrink-0 items-center justify-center rounded-full bg-primary font-semibold text-primary-foreground ${compact ? "size-6 text-[11px]" : "size-7 text-xs"}`} aria-hidden="true">M</span>;
  const assistant = (body: React.ReactNode) => <div className={`flex min-w-0 ${compact ? "gap-2.5" : "gap-3"}`}>{avatar}<div className="min-w-0 flex-1">{body}</div></div>;
  return <div className={`min-w-0 max-w-full ${compact ? "space-y-6" : "space-y-8"}`} aria-live="polite">
    {messages.map(item => <article key={item.id}>
      <time className="sr-only" dateTime={item.created_at}>{item.created_at}</time>
      {item.role === "user" ? <p className={bubble}>{item.content}</p> : assistant(<>{item.plan && <Plan steps={item.plan} done collapsed />}<AiToolActivity tools={item.tools ?? []} /><AiMessage content={item.content} />{item === messages.at(-1) && !pending && <FollowUps items={item.followUps ?? []} compact={compact} />}</>)}
    </article>)}
import { ArrowUp, Square } from "lucide-react";

/** Composer shared by the AI page and the Ask Moneo panel. Enter sends (or queues while busy), Shift+Enter adds a line. */
export function ChatComposer({ id, label, value, onChange, onSubmit, onStop, busy, disabled = false, placeholder, compact = false, busyText }: {
  id: string; label: string; value: string; onChange: (value: string) => void; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void;
  onStop: () => void; busy: boolean; disabled?: boolean; placeholder: string; compact?: boolean; busyText: string;
}) {
  const button = `flex items-center justify-center rounded-full bg-primary text-primary-foreground hover:opacity-90 ${compact ? "size-8" : "size-9"}`;
  return <form onSubmit={onSubmit} className="rounded-3xl border border-border bg-card p-2 shadow-sm transition-colors focus-within:border-muted-foreground/60">
    <label htmlFor={id} className="sr-only">{label}</label>
    <textarea id={id} value={value} onChange={event => onChange(event.target.value)} onKeyDown={event => { if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) { event.preventDefault(); event.currentTarget.form?.requestSubmit(); } }}
      maxLength={4000} rows={1} placeholder={placeholder} className={`block w-full resize-none bg-transparent [field-sizing:content] outline-none! ${compact ? "max-h-48 min-h-10 px-2.5 py-2 text-sm" : "max-h-60 min-h-12 px-3 py-2.5 text-[15px]"}`} />
    <div className={`flex items-center justify-between gap-3 ${compact ? "pl-2.5" : "pl-3"}`}><span role={busy ? "status" : undefined} className="text-xs text-muted-foreground">{busy ? busyText : ""}</span>
      <div className="flex gap-1.5">{busy && <button type="button" onClick={onStop} aria-label="Stop" className={button}><Square className={`${compact ? "size-3" : "size-3.5"} fill-current`} aria-hidden="true" /></button>}
        {/* While a reply runs, sending queues the message. */}
        {(!busy || value.trim()) && <button disabled={disabled || !value.trim()} aria-label={busy ? "Queue message" : "Send"} className={`${button} disabled:opacity-30`}><ArrowUp className={compact ? "size-4" : "size-5"} aria-hidden="true" /></button>}</div></div>
  </form>;
}

